<template><section class="cart"><h1>Your cart</h1><div v-if="store.loading">Loading cart...</div><div v-else-if="!store.items.length" class="empty">Your cart is empty.<router-link to="/products">Browse products</router-link></div><div v-else><article v-for="item in store.items" :key="item.productId" class="line"><span class="emoji">{{ item.emoji }}</span><div class="info"><strong>{{ item.productName }}</strong><small>Rs.{{ item.price }} each</small></div><div class="qty"><button @click="change(item,-1)">−</button>{{ item.quantity }}<button @click="change(item,1)">+</button></div><b>Rs.{{ (item.price*item.quantity).toFixed(2) }}</b><button class="remove" @click="store.removeItem(item.productId)">Remove</button></article><div class="total"><strong>Total: Rs.{{ store.total.toFixed(2) }}</strong><router-link class="checkout" to="/checkout">Checkout</router-link></div></div></section></template>
<script>
import { useCartStore } from '../stores/cartStore.js'; export default { computed:{store(){return useCartStore()}}, created(){this.store.fetchCart()}, methods:{change(item,delta){const q=item.quantity+delta;q>0?this.store.updateQuantity(item.productId,q):this.store.removeItem(item.productId)}}}
</script>
<style scoped>.cart{max-width:900px;margin:auto}.cart h1{margin-bottom:25px}.line{display:flex;align-items:center;gap:17px;background:#fff;padding:18px;margin:10px 0;border-radius:10px}.emoji{font-size:1.6rem}.info{display:grid;gap:5px;flex:1}.info small{color:#68738a}.qty{display:flex;align-items:center;gap:12px}.qty button{border:0;background:#eef1f8;width:28px;height:28px;border-radius:5px}.remove{border:0;background:none;color:#c0392b}.total{display:flex;justify-content:flex-end;align-items:center;gap:25px;margin-top:25px;font-size:1.2rem}.checkout{background:#536dfe;color:#fff;padding:12px 18px;border-radius:7px;text-decoration:none}.empty{text-align:center;padding:50px;background:#fff;border-radius:10px}.empty a{display:block;margin-top:12px;color:#536dfe}</style>
